-- 003_content_from_fichas.sql
-- Generado por scripts/generate_fichas_seed.py.
-- Fuente: fichas DOCX entregadas para XploraSG.
-- Los 20 lugares y 16 servicios permanecen como borrador.

WITH ficha (
  municipio, categoria, slug, nombre, descripcion, direccion, info_acceso,
  horarios, costo, actividades, servicios_disponibles, accesibilidad,
  recomendaciones, contacto, fuente_verificacion, latitud, longitud
) AS (
  VALUES
    ('Arroyo Seco', 'Naturaleza', 'las-adjuntas', 'Las Adjuntas', 'Punto donde convergen las aguas termales y transparentes del Río Santa María con las aguas frías y de tono azul del Río Ayutla, creando una temperatura ideal y una vista espectacular.', 'Coordenadas aproximadas: 21.3934, -99.5852. Enlace de Google Maps pendiente. Punto de acceso en la comunidad de Ayutla.', 'Desde la cabecera municipal de Arroyo Seco, tomar la carretera principal hacia Jalpan y desviarse en Ayutla. El acceso final es de terracería, recomendable vehículo alto o caminar.', 'Abierto todos los días. Se recomienda visitar con luz de día (08:00 - 18:00).', 'Entrada general libre, pero los ejidatarios pueden cobrar una cuota de mantenimiento de $30 a $50 MXN por vehículo o campamento.', 'Natación, campismo, senderismo, fotografía y observación de flora/fauna.', 'Estacionamiento rústico, asadores y renta de cabañas cercanas en la comunidad de Ayutla.', 'Acceso complicado para personas con movilidad reducida debido al terreno irregular de terracería y piedras de río.', 'Llevar repelente ecológico, zapatos para agua, no dejar basura. En temporada de lluvias fuertes el caudal puede ser peligroso.', 'No cuenta con administración centralizada; contactar a prestadores de servicios de Ayutla.', 'de-paseo.com (Octubre 2026)', 21.3934, -99.5852),
    ('Arroyo Seco', 'Cultura y Arqueología', 'mision-de-san-miguel-conca', 'Misión de San Miguel Concá', 'Es la más pequeña de las cinco misiones de la Sierra Gorda y la primera en terminarse (1754). Se caracteriza por la presencia del águila bicéfala (símbolo de los Habsburgo) y detalles indígenas como flores, follaje y animales.', 'Frente a la plaza principal de Concá. Enlace a Google Maps pendiente.', 'Accesible por carretera pavimentada (Carretera Federal 69, Jalpan - Río Verde).', 'Abierta durante el día para visitas, misas en horarios dominicales y festivos.', 'Entrada libre.', 'Turismo religioso, cultural, arquitectónico y fotografía.', 'En el pueblo hay tiendas, baños públicos y opciones de comida.', 'Accesible en la entrada, algunas zonas interiores pueden tener desniveles.', 'Guardar respeto, no usar flash en el interior.', 'Parroquia local de Concá.', 'volviendoalabiblia.com.mx (Octubre 2026)', NULL, NULL),
    ('Arroyo Seco', 'Naturaleza', 'sotano-del-barro', 'Sótano del Barro', 'Una de las simas (cavernas verticales) más grandes del mundo con una profundidad de 410 metros y un diámetro de 500 metros. Es hogar y refugio principal de la guacamaya verde, una especie en peligro de extinción.', 'Ubicado en la sierra a 2 horas de camino a pie desde la comunidad de Santa María de los Cocos.', 'En auto hasta Santa María de los Cocos, y de ahí se emprende una caminata guiada cuesta arriba (aprox. 1.5 a 2 horas).', 'El recorrido debe iniciar antes del amanecer (aprox. 4:00 am) para observar el avistamiento de las guacamayas al salir el sol.', 'Se debe pagar a los guías comunitarios locales autorizados. Costos varían.', 'Senderismo de montaña, observación de aves (guacamaya verde), paisajismo.', 'Servicios nulos en la cima. En la comunidad base se ofrece comida y estacionamiento.', 'Solo para personas con buena condición física. NO accesible para sillas de ruedas.', 'Llevar linterna frontal, ropa abrigadora, agua y calzado de senderismo. Está prohibido gritar o hacer ruido al borde del sótano.', 'Cooperativa comunitaria de Santa María de los Cocos.', 'ecured.cu (Octubre 2026)', NULL, NULL),
    ('Jalpan de Serra', 'Cultura y Arqueología', 'mision-de-jalpan', 'Misión de Santiago Apóstol de Jalpan', 'Fue la primera de las cinco misiones franciscanas construidas bajo la dirección de Fray Junípero Serra en la Sierra Gorda (construida entre 1751 y 1758). Destaca por su fachada de estilo barroco mestizo en estuco, donde elementos europeos se mezclan con flora y símbolos indígenas.', 'Frente a la plaza principal de Jalpan de Serra.', 'Ubicada en el corazón de la cabecera municipal, sobre la Plaza Principal, fácilmente accesible a pie o en vehículo.', '09:00 a 18:00 hrs todos los días.', 'Entrada gratuita.', 'Turismo cultural y religioso, fotografía arquitectónica.', 'Servicios comerciales, restaurantes y baños públicos disponibles alrededor de la plaza principal.', 'Alta accesibilidad. Atrio y nave principal a nivel de calle, apto para personas con movilidad reducida.', 'Se recomienda observar los detalles de la fachada al atardecer para apreciar el relieve.', 'Parroquia de Santiago Apóstol.', 'INAH / mexicodesconocido.com.mx (Octubre 2026)', NULL, NULL),
    ('Jalpan de Serra', 'Cultura y Arqueología', 'mision-de-tancoyol', 'Misión de Nuestra Señora de la Luz de Tancoyol', 'Misión franciscana que se caracteriza por poseer la fachada más elaborada iconográficamente de las cinco misiones, dedicada a Nuestra Señora de la Luz. Fue construida por las comunidades pames bajo supervisión franciscana.', 'Comunidad de Tancoyol, Jalpan de Serra.', 'A 45 minutos al noreste de Jalpan de Serra, tomando la desviación en la carretera 120 hacia Tancoyol.', '09:00 a 17:00 hrs todos los días.', 'Entrada gratuita.', 'Turismo cultural y religioso, fotografía.', 'Servicios básicos en la pequeña comunidad de Tancoyol.', 'Accesible en silla de ruedas hasta el atrio; escalones bajos en la entrada principal.', 'Cargar gasolina en Jalpan antes de tomar la desviación, ya que en la ruta hay menos servicios.', 'Diócesis de Querétaro.', 'UNESCO / Turismo de Querétaro (Octubre 2026)', NULL, NULL),
    ('Jalpan de Serra', 'Naturaleza', 'presa-jalpan', 'Presa de Jalpan', 'Un oasis artificial que se ha integrado perfectamente al ecosistema de la Sierra Gorda. Fue declarada sitio Ramsar (humedal de importancia internacional) por la gran cantidad de aves migratorias que recibe.', 'A 1.5 km al sur de la plaza principal de Jalpan.', 'Se puede llegar caminando desde el centro de Jalpan a través del andador arbolado, o en vehículo en 5 minutos.', 'Espacio público abierto 24 horas (horario recomendado: 07:00 a 19:00 hrs).', 'Acceso libre.', 'Paseos en lancha, kayak, pesca deportiva, ciclismo de montaña (circuito alrededor de la presa), observación de aves.', 'Renta de kayaks, palapas, asadores, renta de bicicletas, cabañas ecoturísticas aledañas.', 'Alta en el andador principal y zonas de palapas. Baja en los senderos perimetrales no pavimentados.', 'Llevar binoculares para observación de aves. Usar chaleco salvavidas para actividades acuáticas.', 'Turismo Municipal de Jalpan de Serra.', 'sitiosramsar.conanp.gob.mx (Octubre 2026)', NULL, NULL),
    ('Jalpan de Serra', 'Cultura y Arqueología', 'tancama', 'Zona Arqueológica Tancama', 'Asentamiento de la cultura huasteca cuyo nombre significa ''Cerro de fuego''. Destaca por su adaptación a la topografía de la sierra, con plazas escalonadas (El Mirador, Santiago, La Promesa) y arquitectura de basamentos circulares.', 'Aproximadamente a 30 minutos de la cabecera municipal de Jalpan. [Enlace a Google Maps]', 'Desde Jalpan, tomar la carretera federal 120 hacia Xilitla y luego la desviación asfaltada señalizada hacia Tancama.', 'Martes a Domingo de 09:00 a 16:00 hrs.', 'Aprox $75 MXN (Exentos: menores, estudiantes e INAPAM).', 'Turismo arqueológico, observación de basamentos, fotografía de paisaje serrano.', 'Custodia del INAH, taquilla, sanitarios, señalética.', 'Baja accesibilidad para sillas de ruedas por ser terreno natural y plataformas escalonadas.', 'Llevar agua y protector solar. Respetar los senderos delimitados.', 'INAH Centro Querétaro.', 'INAH (Octubre 2026)', NULL, NULL),
    ('Landa de Matamoros', 'Cultura y Arqueología', 'mision-de-landa', 'Misión de Santa María del Agua de Landa', 'Construida entre 1761 y 1764, es considerada la misión con la fachada más ornamentada y teológicamente profunda. Dedicada a la Purísima Concepción, representa la Ciudad de Dios y fue el punto de partida misionero hacia Texas y California.', 'Centro Histórico de Landa de Matamoros. [Enlace a Google Maps]', 'Accesible por la carretera federal 120 (San Juan del Río - Xilitla). Se encuentra en la plaza principal del municipio, a 20 km de Jalpan.', 'Lunes a Domingo de 08:00 a 18:00 hrs.', 'Entrada libre.', 'Turismo religioso y cultural, arquitectura histórica y fotografía.', 'Alimentos, cajeros y pequeños comercios en los alrededores de la plaza.', 'Acceso pavimentado y a nivel de calle.', 'Procurar silencio en interiores y no utilizar flash fotográfico.', 'Parroquia local de Landa.', 'queretaro.travel (Octubre 2026)', NULL, NULL),
    ('Landa de Matamoros', 'Cultura y Arqueología', 'mision-de-tilaco', 'Misión de San Francisco del Valle de Tilaco', 'Es la misión más pequeña pero con una ornamentación ingenua y alegre que incluye sirenas, un elemento inusual en el arte sacro. Construida entre 1754 y 1762 en un pequeño valle rodeado de montañas.', 'Comunidad de Tilaco, Landa de Matamoros. [Enlace a Google Maps]', 'Desde Landa, continuar por la federal 120 y tomar la desviación pavimentada hacia Tilaco (aprox. 30 minutos).', 'Lunes a Domingo de 09:00 a 17:00 hrs.', 'Entrada libre.', 'Turismo cultural y arquitectónico.', 'Fondas familiares, pequeñas posadas locales.', 'Rampa en la entrada, plaza plana, sin embargo los accesos secundarios pueden tener desniveles.', 'Ideal visitarla durante el día para apreciar mejor el valle y los detalles arquitectónicos.', 'Delegación comunitaria.', 'mexicodesconocido.com.mx (Octubre 2026)', NULL, NULL),
    ('Landa de Matamoros', 'Naturaleza', 'neblinas', 'Comunidad de Neblinas / Río Neblinas', 'Es el punto más oriental del estado de Querétaro, caracterizado por sus bosques de niebla, cafetales y su cercanía con el río Moctezuma. Destaca la Cascada de Neblinas y su exuberante biodiversidad.', 'Comunidad de Neblinas, al este de Landa de Matamoros. [Enlace a Google Maps]', 'El camino es de terracería sinuosa. Se recomienda vehículo 4x4 o camioneta alta. Desde la carretera 120, tomar la desviación en La Lagunita.', 'Abierto 24 hrs, pero se requiere viajar con luz de día.', 'Generalmente gratuito, cuotas ejidales simbólicas.', 'Senderismo, campismo, fotografía de paisajes, convivencia rural.', 'Servicios muy básicos en la comunidad (tiendas de abarrotes y hospedaje rústico muy limitado).', 'Dificultad alta; caminos de terracería resbaladiza en temporada de lluvias. No apto para movilidad reducida.', 'Viajar en temporada seca, llevar provisiones y preguntar por guías locales.', 'Autoridades ejidales de Neblinas.', 'mapcarta.com (Octubre 2026)', NULL, NULL),
    ('Landa de Matamoros', 'Naturaleza', 'rio-verdito', 'Cascada de Río Verdito', 'Hermosa cascada rodeada de vegetación tipo selva baja y bosque. Sus aguas corren limpias y cristalinas formando pozas naturales de tonos verde esmeralda.', 'Comunidad de Río Verdito, Landa de Matamoros. [Enlace a Google Maps]', 'Desde la carretera principal (120), tomar la desviación hacia Agua Zarca y posteriormente hacia Río Verdito. Camino pavimentado hasta el pueblo, seguido de un sendero peatonal.', 'Luz de día (07:00 a 18:00 hrs).', 'Contribución comunitaria de entre $20 y $50 MXN.', 'Natación, senderismo, ecoturismo y días de campo.', 'Comedores de comida típica, baños rústicos y zonas de campamento (administrados por la comunidad).', 'El sendero hacia la cascada incluye escalones de piedra y pendientes resbaladizas; no es apto para sillas de ruedas.', 'Llevar repelente ecológico, zapato acuático, bolsas para basura.', 'Comité turístico de Río Verdito.', 'mexico.pueblosamerica.com (Octubre 2026)', NULL, NULL),
    ('Peñamiller', 'Naturaleza', 'balneario-el-oasis', 'Balneario El Oasis', 'Un balneario natural y semi-urbanizado escondido entre las montañas semiáridas de Peñamiller. Alimentado por manantiales de aguas cristalinas, es un verdadero ''oasis'' en medio de la Sierra Gorda que ofrece descanso y diversión para toda la familia.', 'A pocos kilómetros de la cabecera municipal de Peñamiller. [Enlace a Google Maps]', 'Accesible por carretera pavimentada y un tramo corto de terracería en buenas condiciones. Ubicado cerca del cauce del río.', 'Martes a Domingo de 09:00 a 18:00 hrs (Sujeto a cambios).', 'Entrada general aproximada: $70 - $100 MXN.', 'Natación en albercas, campismo, convivencias familiares, días de campo.', 'Albercas familiares y chapoteaderos, asadores, sanitarios, regaderas, áreas verdes y zona de acampar.', 'Zonas planas con andadores de concreto, accesible para personas con movilidad reducida (hasta el área de albercas).', 'Llevar bloqueador solar biodegradable, no introducir envases de vidrio. Fines de semana suele estar concurrido.', 'Administración local de El Oasis.', 'ciudadypoder.mx (Octubre 2026)', NULL, NULL),
    ('Peñamiller', 'Naturaleza', 'canon-del-paraiso', 'Cañón del Paraíso', 'Un espectacular desfiladero natural flanqueado por inmensas paredes de mármol negro. Es surcado por el río Extoraz, lo que lo convierte en un paisaje místico y desafiante ideal para los amantes del turismo de aventura y el senderismo extremo.', 'Comunidad de Río Blanco, Peñamiller. [Enlace a Google Maps]', 'Se llega hasta la comunidad de Río Blanco en auto, y a partir de ahí se debe realizar una caminata (senderismo acuático) por el cauce del río Extoraz.', 'Recorridos desde el amanecer hasta media tarde para evitar la noche en el cañón.', 'Acceso gratuito, pero se recomienda ampliamente contratar un guía local ($200-$400 MXN aprox).', 'Senderismo acuático (caminar sobre el río), cañonismo, fotografía de paisaje y observación geológica.', 'Ninguno en el cañón. En la comunidad de Río Blanco hay servicios básicos de tiendas.', 'Muy difícil. Requiere caminar sobre piedras de río, cruzar corrientes de agua y escalar rocas. Inadecuado para sillas de ruedas o niños muy pequeños.', 'Uso obligatorio de chaleco salvavidas (en pozas), zapatos acuáticos o tenis con buen agarre. NO visitar en temporada de lluvias intensas por riesgo de crecidas repentinas.', 'Guías comunitarios de Río Blanco.', 'elsouvenir.com (Octubre 2026)', NULL, NULL),
    ('Peñamiller', 'Cultura y Arqueología', 'vestigios-prehistoricos', 'Vestigios y Pinturas Rupestres en Peñamiller', 'La zona semiárida de Peñamiller alberga antiguas manifestaciones humanas. Destacan restos de asentamientos antiguos de culturas locales y pinturas rupestres que evidencian la importancia de la región como ruta de paso prehispánica.', 'Cerros aledaños a la cabecera municipal. (Zonas no habilitadas turísticamente al 100%). [Enlace a Google Maps]', 'Depende de la zona específica. Generalmente se requiere senderismo desde la cabecera o comunidades cercanas guiado por lugareños.', 'A coordinar con guías locales.', 'Cuota de guía local (variable).', 'Senderismo histórico, exploración cultural y arqueológica.', 'Servicios nulos en las zonas arqueológicas; todos los servicios están en Peñamiller Centro.', 'Ascensos a campo traviesa o senderos irregulares. No apto para movilidad reducida.', 'Contratar obligatoriamente un guía local que conozca los senderos. Prohibido tocar o dañar las pinturas y vestigios.', 'Dirección de Turismo de Peñamiller.', 'mexicotravelclub.com (Octubre 2026)', NULL, NULL),
    ('Pinal de Amoles', 'Naturaleza', 'cuatro-palos', 'Mirador Cuatro Palos', 'Uno de los puntos más altos y espectaculares de la Sierra Gorda. Famoso por su vista panorámica donde el semidesierto se encuentra con los bosques de encino, y por el fenómeno del ''mar de nubes'' durante el amanecer.', 'En lo alto del Cerro de la Media Luna, comunidad de Cuatro Palos. [Enlace a Google Maps]', 'Desviación en la comunidad de La Cañada (Carretera 120), subir por un camino de terracería de aprox. 5 km. Se recomienda vehículo alto o contratar transporte local.', '06:00 a 18:00 hrs (Ideal llegar al amanecer).', 'Acceso aprox: $80 - $100 MXN.', 'Observación de paisajes, fotografía de amaneceres, senderismo, campismo.', 'Guías comunitarios (obligatorios para acceder al mirador), área de acampar, baños rústicos, venta de antojitos los fines de semana.', 'Dificultad media. Caminata en ascenso por sendero de terracería y escalones de piedra. Inadecuado para sillas de ruedas.', 'Llevar ropa muy abrigadora (hace mucho frío de madrugada), calzado de montaña. No subir en caso de tormenta.', 'Comité de Turismo Cuatro Palos.', 'queretaro.travel (Octubre 2026)', NULL, NULL),
    ('Pinal de Amoles', 'Naturaleza', 'el-chuveje', 'Cascada El Chuveje', 'Espléndida caída de agua de casi 30 metros de altura rodeada de un exuberante bosque de álamos, sauces y helechos. Sus aguas cristalinas corren formando pozas naturales.', 'A pocos kilómetros de la cabecera municipal rumbo a Jalpan. [Enlace a Google Maps]', 'Sobre la carretera 120 (San Juan del Río-Xilitla), a unos 18 km de Pinal de Amoles, tomar la desviación señalizada y bajar por terracería hasta el estacionamiento.', 'Lunes a Domingo de 08:00 a 17:00 hrs.', 'Entrada general: $80 MXN aprox.', 'Senderismo ligero, fotografía, observación de flora y fauna, días de campo.', 'Estacionamiento, baños, puestos de comida regional (fines de semana), zona de campamento regulada.', 'Sendero de tierra plano y arbolado de unos 15-20 minutos desde el estacionamiento. Accesible para la mayoría, aunque complicado para sillas de ruedas en temporada de lluvias por el lodo.', 'ESTÁ PROHIBIDO NADAR (es reserva natural para proteger fauna endémica como el ajolote). No introducir bebidas alcohólicas ni mascotas.', 'CONANP / Administración de El Chuveje.', 'huellasdesal.com (Octubre 2026)', NULL, NULL),
    ('Pinal de Amoles', 'Naturaleza', 'mirador-de-cristal', 'Mirador de Cristal (Peña de las Guacamayas)', 'Atractivo turístico reciente que consiste en una plataforma de cristal transparente suspendida a más de 120 metros de altura sobre un acantilado, ofreciendo vistas de vértigo del cañón y la sierra verde.', 'Cercano a la Puerta del Cielo y a la cabecera municipal. [Enlace a Google Maps]', 'Acceso desde la carretera principal 120, a escasos minutos del centro de Pinal de Amoles.', 'Lunes a Domingo de 09:00 a 18:00 hrs (Sujeto a clima).', 'Acceso aprox: $150 MXN (Incluye uso del mirador de cristal por tiempo limitado).', 'Fotografía de aventura, apreciación del paisaje.', 'Fotógrafo en el sitio (opcional con costo extra), sanitarios, tirolesa (en algunos complejos aledaños).', 'Accesible mediante escaleras de madera y metal. Prohibido entrar con zapatos (te prestan cubrecalzado para proteger el cristal).', 'No apto para personas con fobia extrema a las alturas. Seguir las instrucciones de tiempo máximo en la plataforma.', 'Turismo Municipal Pinal de Amoles.', 'pinaldeamoles.travel (Octubre 2026)', NULL, NULL),
    ('San Joaquín', 'Naturaleza', 'cascadas-maravilla', 'Cascadas Maravillas / Cascada Las Maravillas', 'Una impresionante caída de agua rodeada de un paisaje boscoso y húmedo que caracteriza la entrada a la Sierra Gorda. Ideal para desconectarse y disfrutar de la naturaleza en estado puro.', 'Aproximadamente a 20 minutos de la cabecera municipal de San Joaquín. [Enlace a Google Maps]', 'Desde la plaza principal de San Joaquín, se toma un camino de terracería en dirección a la zona boscosa. Se recomienda vehículo alto o cuatrimoto, seguido de una caminata en descenso.', '08:00 a 17:00 hrs (recomedado con luz de día).', 'Aproximadamente $50 MXN (Cuota comunitaria).', 'Senderismo, fotografía de paisaje, días de campo, ecoturismo.', 'Servicios rústicos y básicos administrados por la comunidad local (palapas y venta ocasional de alimentos en temporada alta).', 'Accesibilidad baja. El sendero es de terracería con pendientes pronunciadas y piedras. Inadecuado para sillas de ruedas o personas con movilidad reducida.', 'Llevar calzado con buen agarre (antiderrapante), agua potable, repelente de insectos ecológico. Evitar nadar en épocas de fuertes corrientes.', 'Comunidad local de San Joaquín.', 'mexicodesconocido.com.mx (Octubre 2026)', NULL, NULL),
    ('San Joaquín', 'Naturaleza', 'grutas-de-los-herrera', 'Grutas de los Herrera', 'Espectaculares cavernas milenarias acondicionadas para el turismo, donde se pueden admirar impresionantes formaciones de estalactitas y estalagmitas que la naturaleza ha esculpido durante miles de años.', 'A tan solo 10 minutos de la cabecera municipal de San Joaquín. [Enlace a Google Maps]', 'Acceso pavimentado muy cerca del centro de San Joaquín. Hay señalamientos claros sobre la carretera principal.', 'Martes a Domingo de 10:00 a 17:00 hrs.', 'Entrada general: $40 - $50 MXN.', 'Exploración de cavernas, fotografía geológica, turismo familiar.', 'Estacionamiento, sanitarios, andadores de concreto iluminados y escalinatas con pasamanos en el interior de la gruta.', 'El interior está adaptado con escaleras y barandales seguros, pero no es accesible para sillas de ruedas debido a los desniveles naturales de la cueva.', 'Usar zapatos cómodos y cerrados. No tocar las formaciones rocosas para evitar dañar su crecimiento natural.', 'Administración turística municipal.', 'queretaro.travel / mexicodesconocido.com.mx (Octubre 2026)', NULL, NULL),
    ('San Joaquín', 'Cultura y Arqueología', 'ranas', 'Zona Arqueológica Ranas', 'Importante centro ceremonial, político y religioso asociado a la explotación minera prehispánica (especialmente el cinabrio) durante el periodo Clásico. Sus estructuras están construidas estratégicamente sobre elevaciones naturales con lajas de piedra.', 'A 3 km al norte de la cabecera municipal de San Joaquín. [Enlace a Google Maps]', 'Camino pavimentado desde el centro de San Joaquín, se puede llegar en vehículo o caminando en aproximadamente 45 minutos.', 'Lunes a Domingo de 09:00 a 17:00 hrs.', 'Entrada general aproximada: $75 MXN (Exentos: menores de 13 años, estudiantes, maestros e INAPAM).', 'Turismo arqueológico, fotografía, conocimiento de las culturas de la Sierra Gorda, observación de las canchas del juego de pelota.', 'Custodia del INAH, taquilla, sanitarios en la entrada, señalética informativa.', 'Terreno irregular, con senderos de terracería y escalinatas prehispánicas. Complicado para personas con movilidad reducida.', 'Llevar sombrero, bloqueador solar y agua. Respetar las delimitaciones y no subir a las estructuras restringidas.', 'INAH Querétaro.', 'mexicodesconocido.com.mx / INAH (Octubre 2026)', NULL, NULL)
)
INSERT INTO public.lugares_turisticos (
  municipio_id, categoria_id, slug, nombre, descripcion, direccion, info_acceso,
  horarios, costo, actividades, servicios_disponibles, accesibilidad,
  recomendaciones, contacto, fuente_verificacion, latitud, longitud,
  estado_aprobacion
)
SELECT
  m.id, c.id, f.slug, f.nombre, f.descripcion, f.direccion, f.info_acceso,
  f.horarios, f.costo, f.actividades, f.servicios_disponibles, f.accesibilidad,
  f.recomendaciones, f.contacto, f.fuente_verificacion, f.latitud, f.longitud,
  'borrador'
FROM ficha AS f
JOIN public.municipios AS m ON m.nombre = f.municipio
JOIN public.categorias AS c ON c.nombre = f.categoria
ON CONFLICT (slug) DO UPDATE SET
  municipio_id = EXCLUDED.municipio_id,
  categoria_id = EXCLUDED.categoria_id,
  nombre = EXCLUDED.nombre,
  descripcion = EXCLUDED.descripcion,
  direccion = EXCLUDED.direccion,
  info_acceso = EXCLUDED.info_acceso,
  horarios = EXCLUDED.horarios,
  costo = EXCLUDED.costo,
  actividades = EXCLUDED.actividades,
  servicios_disponibles = EXCLUDED.servicios_disponibles,
  accesibilidad = EXCLUDED.accesibilidad,
  recomendaciones = EXCLUDED.recomendaciones,
  contacto = EXCLUDED.contacto,
  fuente_verificacion = EXCLUDED.fuente_verificacion,
  latitud = COALESCE(EXCLUDED.latitud, lugares_turisticos.latitud),
  longitud = COALESCE(EXCLUDED.longitud, lugares_turisticos.longitud),
  estado_aprobacion = 'borrador',
  updated_at = CURRENT_TIMESTAMP,
  deleted_at = NULL;

