WITH ficha (
  prestador_slug, municipio, categoria, slug, nombre, descripcion,
  tipo_servicio, rango_precio, contacto, horario, ubicacion, reservacion,
  capacidad_requisitos, accesibilidad, lugares_relacionados,
  fuente_verificacion
) AS (
  VALUES
    ('hotel-hacienda-mision-conca-prestador', 'Arroyo Seco', 'Hospedaje', 'hotel-hacienda-mision-conca', 'Hotel Hacienda Misión Concá', 'Hotel con arquitectura tipo ex-hacienda. Ofrece habitaciones confortables, alberca, amplios jardines y restaurante de comida regional.', 'Hospedaje, Restaurante y Eventos', 'Desde $1,500 MXN a $2,500 MXN por noche.', 'Tel: +52 487 877 4001 / Web: www.hotelesmision.com', 'Recepción 24 horas. Restaurante de 07:00 a 22:00 hrs.', 'Carretera Jalpan-Río Verde Km 32, C.P. 76340, Concá, Qro.', 'Se sugiere reservar a través de su sitio web o vía telefónica.', 'Variedad de habitaciones (sencillas, dobles y suites familiares).', 'Rampas en áreas comunes y habitaciones en planta baja.', 'Misión de San Miguel Concá y Las Adjuntas.', 'Directorio Mexicoo.mx / Datos de cadena hotelera (Octubre 2026)'),
    ('villas-villa-riviera-prestador', 'Arroyo Seco', 'Hospedaje', 'villas-villa-riviera', 'Villas Villa Riviera', 'Conjunto de villas turísticas rodeadas de entorno natural. Ideal para viajes familiares y grupos.', 'Hospedaje (Villas y Cabañas)', 'Desde $1,200 MXN por noche (Cabaña básica).', 'Consultas presenciales o en oficinas de turismo municipal.', 'Horario administrativo de 09:00 a 18:00 hrs.', 'Carretera principal de Arroyo Seco, C.P. 76430.', 'Mediante contacto directo vía WhatsApp.', 'Villas adaptadas para grupos de 4 hasta 12 personas.', 'Acceso rústico, limitaciones para sillas de ruedas en jardines.', 'Río Santa María y Las Adjuntas.', 'villariviera.com.mx (Octubre 2026)'),
    ('restaurante-coral-prestador', 'Arroyo Seco', 'Gastronomía', 'restaurante-coral', 'Restaurante Coral', 'Restaurante tradicional de Arroyo Seco. Ofrece platillos típicos regionales.', 'Alimentación (Restaurante a la carta y comida corrida)', 'Consumo promedio de $120 a $250 MXN por persona.', 'https://www.facebook.com/p/Restaurante-Coral-100067955036860/', 'Lunes a Domingo de 08:00 a 19:00 hrs.', 'Zona céntrica comercial de Arroyo Seco.', 'No requiere reservación previa.', 'Comedor con capacidad aproximada para 30 a 40 personas.', 'Acceso a nivel de calle.', 'Ubicado en la cabecera municipal, paso hacia Sótano del Barro.', 'Facebook Oficial (Octubre 2026)'),
    ('hotel-mision-jalpan-prestador', 'Jalpan de Serra', 'Hospedaje', 'hotel-mision-jalpan', 'Hotel Misión Jalpan', 'Hotel de estilo colonial ubicado justo frente a la Misión principal. Ofrece habitaciones confortables, alberca al aire libre, y restaurante que sirve gastronomía típica regional.', 'Hospedaje, Restaurante', 'Desde $1,800 MXN hasta $3,000 MXN por noche dependiendo de la temporada.', 'Tel: +52 441 296 0445 / Web: hotelesmision.com', 'Recepción 24 horas.', 'Av. Fray Junípero Serra 3, Centro, 76340 Jalpan de Serra, Qro.', 'Vía portal web o por teléfono, políticas de cancelación estándar de 48 hrs.', 'Habitaciones para 2 a 4 personas. Cuenta con áreas para eventos.', 'Rampas en el primer piso y acceso al restaurante para personas con sillas de ruedas.', 'Ubicado a unos pasos de la Misión Santiago Apóstol de Jalpan.', 'Directorio Mexicoo.mx / Conocimiento general (Octubre 2026)'),
    ('cabanas-centro-ecoturistico-presa-jalpan-prestador', 'Jalpan de Serra', 'Hospedaje', 'cabanas-centro-ecoturistico-presa-jalpan', 'Cabañas Centro Ecoturístico Presa Jalpan', 'Cabañas rústicas pero cómodas situadas a orillas de la Presa de Jalpan. Se rentan kayaks, lanchas de pedales y bicicletas de montaña para recorrer los andadores del humedal.', 'Hospedaje (Cabañas) / Renta de lanchas y bicis', 'Cabañas desde $1,200 MXN por noche. Renta de bicicletas y kayaks aprox $100 - $150 MXN por hora.', 'Consultar en el módulo turístico o directamente en la Presa.', 'Oficina de 09:00 a 18:00 hrs. Hospedaje 24 hrs.', 'Carretera Jalpan - Río Verde s/n, a orillas de la Presa Jalpan.', 'Anticipación de 1 semana en temporada baja y 1 mes en temporada alta.', 'Grupos familiares de hasta 6 personas por cabaña.', 'Acceso rústico en terracería, algunas áreas pueden dificultar el paso a sillas de ruedas.', 'Presa de Jalpan (Humedal RAMSAR).', 'Directorio Mexicoo.mx / Conocimiento general (Octubre 2026)'),
    ('restaurantes-tradicionales-del-centro-especialidad-cecina-serrana-prestador', 'Jalpan de Serra', 'Gastronomía', 'restaurantes-tradicionales-del-centro-especialidad-cecina-serrana', 'Restaurantes Tradicionales del Centro (Especialidad: Cecina Serrana)', 'Representación de la gastronomía típica de la zona que incluye cecina serrana, enchiladas huastecas y queretanas, gorditas de maíz quebrado y bocoles.', 'Alimentación (Restaurante regional)', 'Consumo promedio de $150 a $250 MXN por persona.', 'N/A (Atención sin reservación en la mayoría de fondas).', 'Lunes a Domingo de 08:00 a 20:00 hrs.', 'Zona de Portales y Centro Histórico de Jalpan.', 'No requiere reservación.', 'Comedores con mesas de 4 a 8 personas.', 'Fácil acceso desde la plaza principal pavimentada.', 'Misión Santiago Apóstol de Jalpan.', 'Directorio Mexicoo.mx / Gastronomía Regional (Octubre 2026)'),
    ('sierra-gorda-ecotours-operadora-de-grupo-ecologico-sierra-gorda-prestador', 'Jalpan de Serra', 'Aventura', 'sierra-gorda-ecotours-operadora-de-grupo-ecologico-sierra-gorda', 'Sierra Gorda Ecotours / Operadora de Grupo Ecológico Sierra Gorda', 'Operadora turística oficial comunitaria. Ofrece recorridos guiados por las misiones franciscanas, talleres de cerámica, caminatas en la naturaleza, observación de aves y paquetes integrales con transporte y comida.', 'Guías Turísticos y Tour Operador Ecológico', 'Tours desde $400 MXN hasta paquetes de varios días de $4,000+ MXN por persona.', 'Tel: +52 441 296 0700 / Web: sierragordaecotours.com', 'Oficinas: Lunes a Sábado de 09:00 a 18:00 hrs.', 'Centro de Información Turística, Juárez s/n, Centro, Jalpan de Serra.', 'Requiere reservación previa en línea o vía telefónica para asegurar disponibilidad de guías.', 'Atienden desde viajeros individuales hasta grupos grandes (camiones).', 'Las oficinas son accesibles; la accesibilidad de los recorridos depende del paquete elegido.', 'Misión Jalpan, Presa de Jalpan y gestión de visitas a la Reserva de la Biosfera en general.', 'sierragordaecotours.com (Octubre 2026)'),
    ('casa-de-las-artesanias-talleres-locales-prestador', 'Jalpan de Serra', 'Servicios Comunitarios', 'casa-de-las-artesanias-talleres-locales', 'Casa de las Artesanías / Talleres Locales', 'Espacio dedicado a la exhibición y venta de productos regionales: cerámica policromada, textiles bordados, cestería, miel, licores de frutas, café serrano y talabartería elaborada por las comunidades.', 'Venta de Artesanías y Productos Locales', 'Productos desde $50 MXN (souvenirs) hasta $2,000+ MXN (piezas grandes de cerámica).', 'Venta directa en tienda.', 'Lunes a Domingo de 10:00 a 19:00 hrs.', 'A un costado de la plaza principal y en el interior de los portales del centro histórico.', 'No requiere cita, entrada libre.', 'Abierto al público general.', 'Acceso nivelado para sillas de ruedas en la mayoría de las tiendas ubicadas en el centro.', 'Misión Santiago Apóstol de Jalpan y Centro Histórico.', 'Conocimiento General de Turismo Qro. (Octubre 2026)'),
    ('hotel-plaza-landa-prestador', 'Landa de Matamoros', 'Hospedaje', 'hotel-plaza-landa', 'Hotel Plaza Landa', 'Hotel céntrico ubicado frente a la Misión. Ofrece habitaciones familiares con aire acondicionado, Wi-Fi y vistas a la plaza, siendo una de las opciones más cómodas en pleno centro de Landa.', 'Hospedaje', 'Habitaciones desde $900 MXN a $1,500 MXN por noche.', 'Airbnb o Booking (Hotel Plaza Landa)', 'Recepción en horarios diurnos.', 'Frente a la plaza principal, Centro de Landa de Matamoros.', 'Mediante plataforma digital (Airbnb/Booking).', 'Habitaciones para 2 a 4 personas.', 'El edificio cuenta con múltiples pisos, acceso por escaleras.', 'Misión de Santa María del Agua de Landa.', 'Airbnb (Octubre 2026)'),
    ('pollos-brandon-comedores-de-landa-prestador', 'Landa de Matamoros', 'Gastronomía', 'pollos-brandon-comedores-de-landa', 'Pollos Brandon / Comedores de Landa', 'Uno de los lugares de comida más populares y valorados por los lugareños en Landa de Matamoros. Ofrecen pollos asados, platillos típicos, gorditas y antojitos mexicanos ideales para reponer energía tras un día de expedición.', 'Alimentación (Comedor Local)', 'Consumo promedio de $100 a $150 MXN por persona.', 'Atención directa en mostrador.', 'Lunes a Domingo desde mediodía hasta la tarde/noche.', 'Zona Centro, Landa de Matamoros.', 'No requiere reservación.', 'Mesas compartidas para grupos pequeños.', 'Acceso a nivel de calle.', 'Centro de Landa de Matamoros.', 'Restaurant Guru Landa (Octubre 2026)'),
    ('campamento-y-cabanas-el-oasis-prestador', 'Peñamiller', 'Hospedaje', 'campamento-y-cabanas-el-oasis', 'Campamento y Cabañas El Oasis', 'Alojamiento en cabañas rústicas y renta de espacios para acampar a la orilla del río Extoraz, dentro de las instalaciones del balneario natural. Ideal para turismo de descanso y ecoturismo.', 'Hospedaje (Cabañas y Camping)', 'Cabañas desde $800 MXN a $1,500 MXN por noche. Camping: $150 MXN por casa de campaña.', 'WhatsApp: +52 441 292 9000 (Aproximado / A través de su FB Oficial)', 'Abierto 24 horas para huéspedes. Entrada recomendada antes de las 18:00 hrs.', 'Comunidad Adjuntas de Higueras, a 15 km de la cabecera municipal.', 'Mediante mensaje a la página de Facebook ''Eloasis Semidesierto'' o WhatsApp con al menos 1 semana de anticipación.', 'Cabañas dobles o familiares de hasta 8 personas.', 'Accesible hasta el área de acampar y algunas cabañas en planta baja.', 'Balneario El Oasis, Río Extoraz.', 'Facebook Oficial Eloasis Semidesierto (Octubre 2026)'),
    ('guias-locales-comunitarios-rio-blanco-prestador', 'Peñamiller', 'Aventura', 'guias-locales-comunitarios-rio-blanco', 'Guías Locales Comunitarios - Río Blanco', 'Servicio de guianza experta para recorrer de manera segura el cauce del río Extoraz y explorar las profundidades de las imponentes paredes de mármol del Cañón del Paraíso. Proveen equipo básico y recomendaciones.', 'Guía Turístico / Cañonismo', 'Desde $150 a $300 MXN por persona o tarifas grupales a convenir.', 'Contacto a la llegada a la comunidad o vía Turismo del Municipio (Tel: 442 406 7956 / 442 120 5652).', 'Recorridos desde las 07:00 hasta las 15:00 hrs (para evitar que oscurezca en el cañón).', 'Comunidad de Río Blanco, entrada al Cañón del Paraíso.', 'Se sugiere contactarlos 1 o 2 días antes, especialmente en temporada alta o fines de semana.', 'Grupos desde 2 hasta 15 personas por guía.', 'No accesible para sillas de ruedas; requiere esfuerzo físico, cruce de ríos y caminata sobre piedras.', 'Cañón del Paraíso, Río Extoraz.', 'ivandeviaje.com / mexicodesconocido.com.mx (Octubre 2026)'),
    ('restaurantes-tradicionales-y-fondas-penamiller-prestador', 'Peñamiller', 'Gastronomía', 'restaurantes-tradicionales-y-fondas-penamiller', 'Restaurantes Tradicionales y Fondas (Peñamiller)', 'Establecimientos de comida regional que ofrecen el platillo estrella de la región: ''El Chivo Tapeado'' (carne de chivo de leche preparada con chiles secos, horneada en olla de barro), además de gorditas, nopales con pipián y atole de teja.', 'Alimentación (Restaurante / Fonda)', 'Platillos desde $100 a $250 MXN.', 'Atención directa en los establecimientos.', 'Todos los días de 08:00 a 19:00 hrs. El chivo tapeado suele prepararse principalmente los fines de semana o bajo pedido.', 'Alrededor de la Plaza Principal y mercado de Peñamiller.', 'Para grandes grupos o asegurar el ''Chivo Tapeado'' en día de semana, se requiere encargo previo.', 'Mesas familiares (hasta 30 personas dependiendo del local).', 'Accesos nivelados en las fondas del centro histórico.', 'Centro Histórico de Peñamiller y rutas a los balnearios.', 'Turismo del Estado de Querétaro (Octubre 2026)'),
    ('campamento-y-zona-ecologica-campo-alegre-prestador', 'San Joaquín', 'Hospedaje', 'campamento-y-zona-ecologica-campo-alegre', 'Campamento y Zona Ecológica Campo Alegre', 'Espectacular área boscosa llena de pinos y encinos, acondicionada con palapas, asadores, regaderas y cabañas rústicas. Ideal para un retiro de la ciudad, hacer carne asada y pernoctar en la montaña.', 'Hospedaje (Cabañas y Camping)', 'Entrada general: $20 MXN. Derecho de piso para acampar: $100 - $150 MXN por tienda. Cabañas desde $800 MXN.', 'Teléfono Turismo Municipal: (441) 293 5022', 'Ingreso diario de 08:00 a 18:00 hrs. Área de campamento abierta las 24 hrs para huéspedes.', 'A 5 minutos del centro de San Joaquín, sobre la carretera a la Zona Arqueológica de Ranas.', 'Para acampar no se requiere previa reservación, excepto en fechas del Concurso Nacional de Huapango (Abril). Para cabañas, llamar con 15 días de anticipación.', 'Capacidad amplia para cientos de campistas. Cabañas familiares de 4 a 10 personas.', 'Accesible para vehículos y sillas de ruedas en las áreas principales de asadores, aunque los senderos del bosque son irregulares.', 'Zona Arqueológica Ranas (está en la misma ruta).', 'queretaro.travel / mexicodesconocido.com.mx (Octubre 2026)'),
    ('fondas-tradicionales-y-productores-de-licor-prestador', 'San Joaquín', 'Gastronomía', 'fondas-tradicionales-y-productores-de-licor', 'Fondas Tradicionales y Productores de Licor', 'Servicio gastronómico donde se ofrecen platillos locales como carne de cerdo en salsa verde con nopales, enchiladas queretanas y barbacoa de borrego, acompañado de la bebida insignia del municipio: el licor de manzana artesanal.', 'Alimentación y Productos Locales', 'Comidas completas desde $80 a $150 MXN. Botellas de licor de manzana desde $120 MXN.', 'Locales de atención directa al público en el centro.', '08:00 a 18:00 hrs. Licorerías artesanales abren de 10:00 a 19:00 hrs.', 'Mercado Municipal de San Joaquín y restaurantes aledaños a la Plaza Principal.', 'No requiere reservación.', 'Múltiples mesas en el mercado municipal y restaurantes del centro.', 'Las calles del centro y el mercado cuentan con rampas para acceso peatonal.', 'Cercano a las Grutas de los Herrera.', 'escapadas.mexicodesconocido.com.mx (Octubre 2026)'),
    ('renta-y-tours-en-cuatrimoto-san-joaquin-ecotours-prestador', 'San Joaquín', 'Aventura', 'renta-y-tours-en-cuatrimoto-san-joaquin-ecotours', 'Renta y Tours en Cuatrimoto (San Joaquín Ecotours)', 'Recorridos guiados a través de rutas de terracería y senderos boscosos. Es la forma más popular y emocionante de llegar a puntos de difícil acceso como las Cascadas Maravillas o los miradores altos del municipio.', 'Transporte Turístico / Deportes de Aventura', 'Aproximadamente $400 - $600 MXN por hora de recorrido (2 personas por cuatrimoto).', 'Módulo de Información Turística en la Plaza Principal.', '09:00 a 16:00 hrs. Sujeto a condiciones climáticas (no operan con lluvia fuerte).', 'Salidas desde la Plaza Principal de San Joaquín o módulos de información turística.', 'Se pueden contratar en el momento, pero en fines de semana largos se recomienda contactar a Turismo Municipal para asegurar disponibilidad.', 'Grupos guiados de hasta 10 cuatrimotos (20 personas). Edad mínima para manejar: 18 años con licencia.', 'Actividad de aventura extrema. No apta para personas con problemas de espalda o movilidad reducida debido al impacto en terracería.', 'Cascadas Maravillas, Mirador San Antonio.', 'Turismo del Estado de Querétaro (Octubre 2026)')
)
INSERT INTO public.servicios (
  prestador_id, municipio_id, categoria_id, slug, nombre, descripcion,
  tipo_servicio, rango_precio, contacto, horario, ubicacion, reservacion,
  capacidad_requisitos, accesibilidad, lugares_relacionados,
  fuente_verificacion, estado_aprobacion
)
SELECT
  p.id, m.id, c.id, f.slug, f.nombre, f.descripcion, f.tipo_servicio,
  f.rango_precio, f.contacto, f.horario, f.ubicacion, f.reservacion,
  f.capacidad_requisitos, f.accesibilidad, f.lugares_relacionados,
  f.fuente_verificacion, 'borrador'
FROM ficha AS f
JOIN public.prestadores AS p ON p.slug = f.prestador_slug
JOIN public.municipios AS m ON m.nombre = f.municipio
JOIN public.categorias AS c ON c.nombre = f.categoria
ON CONFLICT (slug) WHERE slug IS NOT NULL DO UPDATE SET
  prestador_id = EXCLUDED.prestador_id,
  municipio_id = EXCLUDED.municipio_id,
  categoria_id = EXCLUDED.categoria_id,
  nombre = EXCLUDED.nombre,
  descripcion = EXCLUDED.descripcion,
  tipo_servicio = EXCLUDED.tipo_servicio,
  rango_precio = EXCLUDED.rango_precio,
  contacto = EXCLUDED.contacto,
  horario = EXCLUDED.horario,
  ubicacion = EXCLUDED.ubicacion,
  reservacion = EXCLUDED.reservacion,
  capacidad_requisitos = EXCLUDED.capacidad_requisitos,
  accesibilidad = EXCLUDED.accesibilidad,
  lugares_relacionados = EXCLUDED.lugares_relacionados,
  fuente_verificacion = EXCLUDED.fuente_verificacion,
  estado_aprobacion = 'borrador',
  updated_at = CURRENT_TIMESTAMP,
  deleted_at = NULL;

DO $$
DECLARE
  total_lugares INT;
  total_servicios INT;
BEGIN
  SELECT COUNT(*) INTO total_lugares
  FROM public.lugares_turisticos
  WHERE slug IN ('las-adjuntas', 'mision-de-san-miguel-conca', 'sotano-del-barro', 'mision-de-jalpan', 'mision-de-tancoyol', 'presa-jalpan', 'tancama', 'mision-de-landa', 'mision-de-tilaco', 'neblinas', 'rio-verdito', 'balneario-el-oasis', 'canon-del-paraiso', 'vestigios-prehistoricos', 'cuatro-palos', 'el-chuveje', 'mirador-de-cristal', 'cascadas-maravilla', 'grutas-de-los-herrera', 'ranas') AND deleted_at IS NULL;

  SELECT COUNT(*) INTO total_servicios
  FROM public.servicios
  WHERE slug IN ('hotel-hacienda-mision-conca', 'villas-villa-riviera', 'restaurante-coral', 'hotel-mision-jalpan', 'cabanas-centro-ecoturistico-presa-jalpan', 'restaurantes-tradicionales-del-centro-especialidad-cecina-serrana', 'sierra-gorda-ecotours-operadora-de-grupo-ecologico-sierra-gorda', 'casa-de-las-artesanias-talleres-locales', 'hotel-plaza-landa', 'pollos-brandon-comedores-de-landa', 'campamento-y-cabanas-el-oasis', 'guias-locales-comunitarios-rio-blanco', 'restaurantes-tradicionales-y-fondas-penamiller', 'campamento-y-zona-ecologica-campo-alegre', 'fondas-tradicionales-y-productores-de-licor', 'renta-y-tours-en-cuatrimoto-san-joaquin-ecotours') AND deleted_at IS NULL;

  IF total_lugares <> 20 THEN
    RAISE EXCEPTION 'Se esperaban 20 lugares importados; se encontraron %', total_lugares;
  END IF;
  IF total_servicios <> 16 THEN
    RAISE EXCEPTION 'Se esperaban 16 servicios importados; se encontraron %', total_servicios;
  END IF;
END;
$$;
